def proverb(*pieces, qualifier=None):
    lines = [
        f"For want of a {current} the {next} was lost."
        for current, next in zip(pieces, pieces[1:])
    ]
    if pieces:
        qualifier_prefix = f"{qualifier} " if qualifier else ""
        lines.append(f"And all for the want of a {qualifier_prefix}{pieces[0]}.")
    return lines

